#[requires(a.len() > 0)]
#[ensures(|result: i32|
    // result is a lower bound for all elements
    forall(|j: usize| j < a.len() ==> result <= a[j])
)]
#[ensures(|result: i32|
    // result actually occurs in the array
    exists(|j: usize| j < a.len() && result == a[j])
)]
pub fn min_array(a: &Vec<i32>) -> i32 {
    // We know from the precondition that a.len() >= 1
    let mut min_val = a[0];

    // Iterate over the rest by index so that we can state a loop invariant
    let mut i: usize = 1;
    #[invariant(i <= a.len())]
    #[invariant(forall(|j: usize| j < i ==> min_val <= a[j]))]
    #[invariant(exists(|j: usize| j < i && min_val == a[j]))]
    #[decreases(a.len() - i)]
    while i < a.len() {
        let x = a[i];
        if x < min_val {
            min_val = x;
        }
        i += 1;
    }

    min_val
}

